CREATE OR REPLACE FUNCTION public.rsc_assert_rejection_progress_authority_0173(checked_request_id uuid, actor_id text, checked_person_id uuid, assignment_id uuid, auth_version bigint, checked_action text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.material_requests%ROWTYPE; checked_now timestamptz; eligible bigint;
    ancestors uuid[]; invalid_tree boolean; tree_before jsonb; tree_after jsonb;
BEGIN
    IF checked_action NOT IN ('cancel_return','outbound_return','ship_return') THEN
        RAISE EXCEPTION '0173 invalid progress permission' USING ERRCODE='42501'; END IF;
    PERFORM public.rsc_lock_formal_principal_graph_0026(ARRAY[actor_id]::text[]);
    SELECT * INTO STRICT r FROM public.material_requests WHERE id=checked_request_id;
    IF r.created_by_user_id<>actor_id OR r.requester_user_id<>actor_id OR r.requester_person_id<>checked_person_id OR NOT EXISTS(
        SELECT 1 FROM public.users u JOIN public.people p ON p.id=u.person_id
        JOIN public.organizations org ON org.id=p.organization_id
        WHERE u.id=actor_id AND p.id=checked_person_id AND u.authorization_version=auth_version
          AND u.account_status='active' AND p.employment_status='active' AND org.status='active'
          AND EXISTS(SELECT 1 FROM public.auth_identities i WHERE i.user_id=u.id
            AND i.verified_at IS NOT NULL AND i.revoked_at IS NULL)) THEN
        RAISE EXCEPTION '0173 rejection progress current original requester required' USING ERRCODE='42501';
    END IF;
    WITH RECURSIVE chain AS (
        SELECT id,parent_id,status,ARRAY[id] path,false cycle FROM public.organizations WHERE id=(SELECT organization_id FROM public.people WHERE id=checked_person_id)
        UNION ALL SELECT o.id,o.parent_id,o.status,c.path||o.id,o.id=ANY(c.path)
        FROM chain c JOIN public.organizations o ON o.id=c.parent_id WHERE NOT c.cycle AND cardinality(c.path)<512
    ) SELECT array_agg(id),bool_or(cycle OR status<>'active' OR cardinality(path)>=512),
        jsonb_agg(jsonb_build_array(id,parent_id,status) ORDER BY id) INTO ancestors,invalid_tree,tree_before FROM chain;
    IF ancestors IS NULL OR invalid_tree THEN
        RAISE EXCEPTION '0173 rejection progress requester organization invalid' USING ERRCODE='42501';
    END IF;
    PERFORM 1 FROM public.organizations WHERE id=ANY(ancestors) ORDER BY id FOR SHARE;
    SELECT jsonb_agg(jsonb_build_array(id,parent_id,status) ORDER BY id) INTO tree_after FROM public.organizations WHERE id=ANY(ancestors);
    IF tree_before IS DISTINCT FROM tree_after THEN
        RAISE EXCEPTION '0173 rejection progress requester organization changed' USING ERRCODE='40001';
    END IF;
    checked_now:=clock_timestamp();
    IF EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles role ON role.id=a.role_id
        JOIN public.role_permissions rp ON rp.role_id=role.id JOIN public.permissions p ON p.id=rp.permission_id
        WHERE a.user_id=actor_id AND a.status IN ('scheduled','active') AND a.revoked_at IS NULL
          AND a.valid_from<=checked_now AND (a.valid_to IS NULL OR a.valid_to>checked_now)
          AND role.status='active' AND ((p.resource='material_request' AND p.action='read') OR (p.resource='stock_operation' AND p.action=checked_action))
          AND p.field_code='' AND rp.effect='deny' AND ((a.scope_type='national' AND a.scope_id='*')
            OR (a.scope_type='person' AND lower(replace(a.scope_id,'-',''))=replace(checked_person_id::text,'-',''))
            OR (a.scope_type='organization' AND lower(replace(a.scope_id,'-','')) IN
              (SELECT replace(v::text,'-','') FROM unnest(ancestors) v)))) THEN
        RAISE EXCEPTION '0173 rejection progress explicit requester deny' USING ERRCODE='42501';
    END IF;
    SELECT count(*) INTO eligible FROM public.role_assignments a JOIN public.roles role ON role.id=a.role_id
        WHERE a.user_id=actor_id AND a.status IN ('scheduled','active') AND a.revoked_at IS NULL
          AND a.valid_from<=checked_now AND (a.valid_to IS NULL OR a.valid_to>checked_now)
          AND role.status='active' AND NOT role.is_external AND role.code='technician'
          AND a.scope_type='person' AND lower(replace(a.scope_id,'-',''))=replace(checked_person_id::text,'-','')
          AND EXISTS(SELECT 1 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id
            WHERE rp.role_id=role.id AND rp.effect='allow' AND p.resource='stock_operation' AND p.action=checked_action AND p.field_code='');
    IF eligible<>1 OR NOT EXISTS(SELECT 1 FROM public.role_assignments a JOIN public.roles role ON role.id=a.role_id
        WHERE a.id=assignment_id AND a.user_id=actor_id AND a.status IN ('scheduled','active') AND a.revoked_at IS NULL
          AND a.valid_from<=checked_now AND (a.valid_to IS NULL OR a.valid_to>checked_now)
          AND role.status='active' AND NOT role.is_external AND role.code='technician'
          AND a.scope_type='person' AND lower(replace(a.scope_id,'-',''))=replace(checked_person_id::text,'-','')
          AND EXISTS(SELECT 1 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id
            WHERE rp.role_id=role.id AND rp.effect='allow' AND p.resource='stock_operation' AND p.action=checked_action AND p.field_code='')
          AND EXISTS(SELECT 1 FROM public.role_permissions rp JOIN public.permissions p ON p.id=rp.permission_id
            WHERE rp.role_id=role.id AND rp.effect='allow' AND p.resource='material_request' AND p.action='read' AND p.field_code='')) THEN
        RAISE EXCEPTION '0173 rejection progress unique current requester grant required' USING ERRCODE='42501';
    END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_dispatch_rejection_progress_0173()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
    IF TG_TABLE_NAME='material_request_rejection_progress' THEN
        PERFORM public.rsc_validate_rejection_progress_0173(NEW.id);
    ELSE
        IF NEW.aggregate_type<>'material_request_rejection_progress'
           OR NEW.action NOT IN ('material_request.rejection_return.cancel_registration',
               'material_request.rejection_return.depart','material_request.rejection_return.handover') THEN
            RAISE EXCEPTION '0173 progress audit type mismatch' USING ERRCODE='23514'; END IF;
        PERFORM public.rsc_validate_rejection_progress_0173(NEW.aggregate_id::uuid);
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_guard_rejection_progress_insert_0173()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent public.material_request_rejection_returns%ROWTYPE;
    r public.material_requests%ROWTYPE; prior public.material_request_rejection_progress%ROWTYPE;
    action_permission text; n bigint; input jsonb; expected jsonb; physical_json jsonb;
BEGIN
    PERFORM public.rsc_require_request_open_0169(NEW.request_id);
    SELECT * INTO STRICT r FROM public.material_requests WHERE id=NEW.request_id;
    SELECT * INTO STRICT parent FROM public.material_request_rejection_returns WHERE id=NEW.return_id;
    action_permission:=CASE NEW.action WHEN 'cancel_registration' THEN 'cancel_return'
        WHEN 'depart' THEN 'outbound_return' WHEN 'handover' THEN 'ship_return' END;
    IF action_permission IS NULL THEN RAISE EXCEPTION '0173 invalid action' USING ERRCODE='23514'; END IF;
    PERFORM public.rsc_assert_rejection_progress_authority_0173(NEW.request_id,NEW.actor_user_id,
        NEW.actor_person_id,NEW.actor_role_assignment_id,NEW.authorization_version,action_permission);
    PERFORM public.rsc_validate_rejection_return_0172(parent.id);
    IF parent.request_id<>r.id OR parent.actor_user_id<>NEW.actor_user_id OR parent.actor_person_id<>NEW.actor_person_id
       OR NEW.registration_request_hash<>parent.request_hash OR NEW.request_version<>r.version
       OR NEW.request_version<parent.request_version OR r.status NOT IN ('approved','partially_approved')
       OR EXISTS(SELECT 1 FROM public.material_request_remaining_cancellations WHERE request_id=r.id)
       OR NEW.id='00000000-0000-0000-0000-000000000000'::uuid
       OR NEW.recorded_at<>CURRENT_TIMESTAMP OR NEW.recorded_at<parent.occurred_at
       OR NEW.reason<>btrim(NEW.reason) OR NEW.reason ~ '[[:cntrl:]]'
       OR NEW.idempotency_key_hash !~ '^[a-f0-9]{64}$'
       OR NEW.trace_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:/@+-]{0,159}$' THEN
        RAISE EXCEPTION '0173 progress origin state or coordinate mismatch' USING ERRCODE='23514'; END IF;
    SELECT count(*) INTO n FROM public.material_request_rejection_progress WHERE return_id=parent.id;
    IF NEW.action='handover' THEN
        IF n<>1 THEN RAISE EXCEPTION '0173 one departure required' USING ERRCODE='23514'; END IF;
        SELECT * INTO STRICT prior FROM public.material_request_rejection_progress WHERE return_id=parent.id;
        IF prior.action<>'depart' OR NEW.previous_event_id IS DISTINCT FROM prior.id
           OR NEW.previous_request_hash IS DISTINCT FROM prior.request_hash
           OR NEW.physical_at<prior.physical_at OR NEW.recorded_at<prior.recorded_at THEN
            RAISE EXCEPTION '0173 exact departure required' USING ERRCODE='23514'; END IF;
        IF NEW.carrier<>btrim(NEW.carrier) OR NEW.tracking_no<>btrim(NEW.tracking_no)
           OR NEW.carrier ~ '[[:cntrl:]]' OR NEW.tracking_no ~ '[[:cntrl:]]' THEN
            RAISE EXCEPTION '0173 carrier evidence malformed' USING ERRCODE='23514'; END IF;
    ELSIF n<>0 THEN
        RAISE EXCEPTION '0173 return already progressed' USING ERRCODE='23514';
    END IF;
    IF NEW.physical_at IS NOT NULL AND (NEW.physical_at<parent.occurred_at OR NEW.physical_at>NEW.recorded_at) THEN
        RAISE EXCEPTION '0173 physical time out of range' USING ERRCODE='23514'; END IF;
    physical_json:=CASE WHEN NEW.physical_at IS NULL THEN 'null'::jsonb ELSE to_jsonb(
        to_char(NEW.physical_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS') ||
        CASE WHEN mod(extract(microseconds FROM NEW.physical_at)::bigint,1000000)=0 THEN ''
            ELSE '.'||to_char(NEW.physical_at AT TIME ZONE 'UTC','US') END || 'Z') END;
    input:=jsonb_build_object('expected_request_version',NEW.request_version,'reason',NEW.reason,'action',NEW.action,
        'registration_request_hash',parent.request_hash,'previous_event_id',NEW.previous_event_id::text,
        'previous_request_hash',NEW.previous_request_hash,'physical_at',physical_json,'carrier',NEW.carrier,'tracking_no',NEW.tracking_no);
    expected:=jsonb_build_object('schema','rsc.material_request_rejection_progress.v1','input',input,
        'origin',jsonb_build_object('return_id',parent.id::text,'registration_request_hash',parent.request_hash,
          'registration_evidence_sha256',parent.evidence_sha256,'request_id',r.id::text,'receipt_id',parent.receipt_id::text,
          'receipt_line_id',parent.receipt_line_id::text,'quantity',parent.quantity::text,
          'serial_ids',parent.evidence_jsonb->'input'->'serial_ids'));
    IF NEW.evidence_jsonb IS DISTINCT FROM expected OR NEW.evidence_sha256 IS DISTINCT FROM
       encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex')
       OR NEW.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(
         jsonb_build_object('request_id',r.id::text,'return_id',parent.id::text,'actor_user_id',NEW.actor_user_id,
         'actor_person_id',NEW.actor_person_id::text,'input',input)),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0173 exact progress evidence required' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_guard_rejection_return_insert_0172()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r public.material_requests%ROWTYPE; receipt public.receipts%ROWTYPE;
    line public.receipt_lines%ROWTYPE; ship public.shipment_lines%ROWTYPE;
    outbound public.outbound_postings%ROWTYPE; reservation public.stock_reservations%ROWTYPE;
    source public.stock_accounts%ROWTYPE; transit public.stock_accounts%ROWTYPE;
    policy public.material_inventory_policies%ROWTYPE; expected_origin jsonb; input jsonb; expected jsonb;
    selected_serials jsonb; original_serials jsonb; tracked boolean; origin_count bigint;
BEGIN
    PERFORM public.rsc_require_request_open_0169(NEW.request_id);
    SELECT * INTO STRICT r FROM public.material_requests WHERE id=NEW.request_id;
    PERFORM public.rsc_assert_rejection_return_authority_0172(NEW.request_id,NEW.actor_user_id,
        NEW.actor_person_id,NEW.actor_role_assignment_id,NEW.authorization_version);
    IF r.status NOT IN ('approved','partially_approved') OR NEW.request_version<>r.version
       OR EXISTS(SELECT 1 FROM public.material_request_remaining_cancellations WHERE request_id=r.id)
       OR NEW.id='00000000-0000-0000-0000-000000000000'::uuid
       OR NEW.occurred_at<>CURRENT_TIMESTAMP OR NEW.created_at<>NEW.occurred_at
       OR NEW.return_no !~ '^RJR-[A-F0-9]{32}$' OR NEW.reason<>btrim(NEW.reason) OR NEW.reason ~ '[[:cntrl:]]'
       OR NEW.idempotency_key_hash !~ '^[a-f0-9]{64}$'
       OR NEW.trace_request_id !~ '^[A-Za-z0-9][A-Za-z0-9._:/@+-]{0,159}$' THEN
        RAISE EXCEPTION '0172 return request state or coordinate mismatch' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT receipt FROM public.receipts WHERE id=NEW.receipt_id;
    SELECT * INTO STRICT line FROM public.receipt_lines WHERE id=NEW.receipt_line_id FOR UPDATE;
    SELECT * INTO STRICT ship FROM public.shipment_lines WHERE id=line.shipment_line_id;
    SELECT * INTO STRICT outbound FROM public.outbound_postings WHERE id=ship.outbound_posting_id;
    SELECT * INTO STRICT reservation FROM public.stock_reservations WHERE id=outbound.reservation_id;
    SELECT * INTO STRICT source FROM public.stock_accounts WHERE id=reservation.source_stock_account_id;
    SELECT * INTO STRICT transit FROM public.stock_accounts WHERE id=outbound.target_stock_account_id;
    IF receipt.receiver_person_id<>NEW.actor_person_id OR receipt.id<>line.receipt_id
       OR receipt.shipment_id<>ship.shipment_id OR receipt.request_hash<>NEW.receipt_request_hash
       OR line.condition='normal' OR line.rejected_qty<=0 OR NEW.quantity>line.rejected_qty
       OR outbound.request_id<>r.id OR NEW.revision_id<>outbound.revision_id
       OR NEW.shipment_line_id<>ship.id OR NEW.outbound_posting_id<>outbound.id
       OR NEW.reservation_id<>reservation.id OR NEW.in_transit_account_id<>transit.id
       OR NEW.return_source_account_id<>source.id OR source.availability_bucket<>'available'
       OR transit.availability_bucket<>'in_transit' OR source.material_id<>transit.material_id
       OR source.owner_org_id<>transit.owner_org_id
       OR NOT EXISTS(SELECT 1 FROM public.shipments s WHERE s.id=receipt.shipment_id AND s.target_person_id=NEW.actor_person_id) THEN
        RAISE EXCEPTION '0172 original rejection provenance mismatch' USING ERRCODE='23514'; END IF;
    SELECT count(*) INTO origin_count FROM public.material_inventory_policies p
      WHERE p.material_id=source.material_id AND p.effective_from<=receipt.received_at
        AND (p.effective_to IS NULL OR p.effective_to>receipt.received_at);
    IF origin_count<>1 THEN RAISE EXCEPTION '0172 original policy unavailable' USING ERRCODE='23514'; END IF;
    SELECT * INTO STRICT policy FROM public.material_inventory_policies p
      WHERE p.material_id=source.material_id AND p.effective_from<=receipt.received_at
        AND (p.effective_to IS NULL OR p.effective_to>receipt.received_at);
    tracked:=policy.tracking_mode IN ('serial','lot_and_serial');
    IF EXISTS(SELECT 1 FROM unnest(ARRAY[line.accepted_qty,line.rejected_qty,NEW.quantity]) q
      WHERE q<>round(q,policy.quantity_scale) OR (NOT policy.allow_fraction AND q<>trunc(q))) THEN
        RAISE EXCEPTION '0172 original quantity precision required' USING ERRCODE='23514'; END IF;
    SELECT coalesce(jsonb_agg(serial_id::text ORDER BY serial_id),'[]') INTO original_serials
      FROM public.receipt_serials WHERE receipt_line_id=line.id AND NOT accepted;
    IF (tracked AND jsonb_array_length(original_serials)<>line.rejected_qty)
       OR (NOT tracked AND original_serials<>'[]') THEN
        RAISE EXCEPTION '0172 original rejected serial count mismatch' USING ERRCODE='23514'; END IF;
    IF (SELECT coalesce(sum(quantity),0) FROM public.material_request_rejection_returns claim WHERE receipt_line_id=line.id AND NOT EXISTS(SELECT 1 FROM public.material_request_rejection_progress p WHERE p.return_id=claim.id AND p.action='cancel_registration'))+NEW.quantity>line.rejected_qty THEN
        RAISE EXCEPTION '0172 cumulative return exceeds rejection' USING ERRCODE='23514'; END IF;
    input:=NEW.evidence_jsonb->'input';
    selected_serials:=input->'serial_ids';
    IF jsonb_typeof(selected_serials) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION '0172 selected serial array required' USING ERRCODE='23514'; END IF;
    IF jsonb_array_length(selected_serials)>1000 OR (tracked AND jsonb_array_length(selected_serials)<>NEW.quantity)
       OR (NOT tracked AND selected_serials<>'[]')
       OR selected_serials IS DISTINCT FROM (SELECT coalesce(jsonb_agg(v ORDER BY v),'[]') FROM (SELECT DISTINCT value v FROM jsonb_array_elements(selected_serials)) s)
       OR EXISTS(SELECT 1 FROM jsonb_array_elements(selected_serials) v WHERE NOT original_serials @> jsonb_build_array(v)) THEN
        RAISE EXCEPTION '0172 selected return serials mismatch' USING ERRCODE='23514'; END IF;
    IF input IS DISTINCT FROM jsonb_build_object('expected_request_version',NEW.request_version,'receipt_id',receipt.id::text,
        'receipt_line_id',line.id::text,'receipt_request_hash',receipt.request_hash,'quantity',NEW.quantity::text,
        'serial_ids',selected_serials,'reason',NEW.reason) THEN
        RAISE EXCEPTION '0172 exact input required' USING ERRCODE='23514'; END IF;
    expected_origin:=jsonb_build_object('request_id',r.id::text,'revision_id',outbound.revision_id::text,
        'receipt_id',receipt.id::text,'receipt_line_id',line.id::text,'receipt_request_hash',receipt.request_hash,
        'shipment_line_id',ship.id::text,'outbound_posting_id',outbound.id::text,'reservation_id',reservation.id::text,
        'in_transit_account_id',transit.id::text,'return_source_account_id',source.id::text,'rejected_qty',line.rejected_qty::text,
        'condition',line.condition,'tracking_mode',policy.tracking_mode,
        'quantity_scale',policy.quantity_scale,'allow_fraction',policy.allow_fraction,'rejected_serial_ids',original_serials);
    expected:=jsonb_build_object('schema','rsc.material_request_rejection_return.v1','input',input,'origin',expected_origin);
    IF NEW.evidence_jsonb IS DISTINCT FROM expected OR NEW.evidence_sha256 IS DISTINCT FROM
       encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(expected),'UTF8')),'hex')
       OR NEW.request_hash IS DISTINCT FROM encode(sha256(convert_to(public.rsc_canonical_reconciliation_json_0026(
         jsonb_build_object('request_id',r.id::text,'actor_user_id',NEW.actor_user_id,'actor_person_id',NEW.actor_person_id::text,'input',input)),'UTF8')),'hex') THEN
        RAISE EXCEPTION '0172 rejection return evidence mismatch' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.rsc_guard_rejection_return_serial_0172()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent public.material_request_rejection_returns%ROWTYPE;
BEGIN
    SELECT * INTO STRICT parent FROM public.material_request_rejection_returns WHERE id=NEW.return_id;
    PERFORM 1 FROM public.material_requests WHERE id=parent.request_id FOR UPDATE;
    IF NEW.receipt_line_id<>parent.receipt_line_id OR NOT parent.evidence_jsonb->'input'->'serial_ids' @> to_jsonb(ARRAY[NEW.serial_id::text])
       OR NOT EXISTS(SELECT 1 FROM public.receipt_serials WHERE receipt_line_id=NEW.receipt_line_id AND serial_id=NEW.serial_id AND NOT accepted) THEN
        RAISE EXCEPTION '0172 return serial origin mismatch' USING ERRCODE='23514'; END IF;

    IF EXISTS(SELECT 1 FROM public.material_request_rejection_progress WHERE return_id=parent.id AND action='cancel_registration')
       OR EXISTS(SELECT 1 FROM public.material_request_rejection_return_serials claim
         WHERE claim.receipt_line_id=NEW.receipt_line_id AND claim.serial_id=NEW.serial_id AND claim.return_id<>parent.id
           AND NOT EXISTS(SELECT 1 FROM public.material_request_rejection_progress p
             WHERE p.return_id=claim.return_id AND p.action='cancel_registration')) THEN
        RAISE EXCEPTION '0173 rejected serial already actively claimed' USING ERRCODE='23514'; END IF;
    RETURN NEW;
END;
$function$
